// Generated readable source strings; production minification must not alter teaching examples.
export const dsaAlgorithmSources = {
  "linearSearch": "function linearSearch({ values, target }, emit = () => {}) {\n  for (let i = 0; i < values.length; i++) {\n    emit({ values, active: [i], note: `Compare index ${i}: ${values[i]} with ${target}.` });\n    if (values[i] === target) return i;\n  }\n  return -1;\n}",
  "insertArray": "function insertArray({ values, index, value }, emit = () => {}) {\n  if (index < 0 || index > values.length) throw new RangeError(\"Invalid insertion index\");\n  const a = [...values];\n  a.push(null);\n  emit({ values: a, active: [index], note: \"Reserve one new slot before shifting.\" });\n  for (let i = a.length - 1; i > index; i--) {\n    a[i] = a[i - 1];\n    emit({\n      values: a,\n      active: [i - 1, i],\n      note: `Copy slot ${i - 1} to ${i}; move right to left.`,\n    });\n  }\n  a[index] = value;\n  emit({ values: a, active: [index], note: `Place ${value} in the opening.` });\n  return a;\n}",
  "prefixSum": "function prefixSum({ values, left, right }, emit = () => {}) {\n  const prefix = [0];\n  for (let i = 0; i < values.length; i++) {\n    prefix.push(prefix[i] + values[i]);\n    emit({\n      values,\n      active: [i],\n      auxiliary: prefix,\n      note: `prefix[${i + 1}] = ${prefix[i]} + ${values[i]}.`,\n    });\n  }\n  const result = prefix[right] - prefix[left];\n  emit({\n    values: prefix,\n    active: [left, right],\n    note: `Sum of [${left}, ${right}) = ${prefix[right]} − ${prefix[left]} = ${result}.`,\n  });\n  return result;\n}",
  "twoPointers": "function twoPointers({ values, target }, emit = () => {}) {\n  let left = 0,\n    right = values.length - 1;\n  while (left < right) {\n    const sum = values[left] + values[right];\n    emit({ values, active: [left, right], note: `left=${left}, right=${right}; sum=${sum}.` });\n    if (sum === target) return [left, right];\n    if (sum < target) left++;\n    else right--;\n  }\n  return [];\n}",
  "windowSum": "function windowSum({ values, size }, emit = () => {}) {\n  if (size < 1 || size > values.length) return null;\n  let sum = 0,\n    best = -Infinity;\n  for (let i = 0; i < values.length; i++) {\n    sum += values[i];\n    if (i >= size) sum -= values[i - size];\n    if (i >= size - 1) best = Math.max(best, sum);\n    emit({\n      values,\n      active: Array.from(\n        { length: Math.min(i + 1, size) },\n        (_, j) => Math.max(0, i - size + 1) + j,\n      ),\n      note: `Window ends at ${i}; running sum=${sum}; best complete window=${best === -Infinity ? \"not ready\" : best}.`,\n    });\n  }\n  return best;\n}",
  "reverseList": "function reverseList({ values }, emit = () => {}) {\n  let head = null;\n  for (let i = values.length - 1; i >= 0; i--) head = { value: values[i], next: head };\n  const list = (node) => {\n    const a = [];\n    while (node) {\n      a.push(node.value);\n      node = node.next;\n    }\n    return a;\n  };\n  let previous = null,\n    current = head;\n  while (current) {\n    const next = current.next;\n    current.next = previous;\n    previous = current;\n    current = next;\n    emit({\n      kind: \"linked\",\n      values: list(previous),\n      auxiliary: list(current),\n      note: \"Save next, redirect current.next, then advance previous and current. Top: reversed prefix; bottom: untouched suffix.\",\n    });\n  }\n  return list(previous);\n}",
  "listInsert": "function listInsert({ values, index, value }, emit = () => {}) {\n  if (index < 0 || index > values.length) throw new RangeError(\"Invalid insertion index\");\n  const dummy = { next: null };\n  let tail = dummy;\n  for (const value of values) {\n    tail.next = { value, next: null };\n    tail = tail.next;\n  }\n  let previous = dummy;\n  for (let i = 0; i < index; i++) {\n    previous = previous.next;\n    emit({\n      kind: \"linked\",\n      values,\n      active: [i],\n      note: `Traverse to predecessor: ${i + 1} link(s) followed.`,\n    });\n  }\n  previous.next = { value, next: previous.next };\n  const result = [];\n  for (let n = dummy.next; n; n = n.next) result.push(n.value);\n  emit({\n    kind: \"linked\",\n    values: result,\n    active: [index],\n    note: \"new.next receives the old successor; predecessor.next receives new.\",\n  });\n  return result;\n}",
  "cycleDetect": "function cycleDetect({ next }, emit = () => {}) {\n  let slow = next.length ? 0 : null,\n    fast = slow;\n  while (fast !== null && next[fast] !== null) {\n    slow = next[slow];\n    fast = next[next[fast]];\n    emit({\n      kind: \"graph\",\n      values: next.map((_, i) => i),\n      edges: next.flatMap((to, from) => (to === null ? [] : [[from, to]])),\n      active: [slow, fast],\n      note: `Slow at ${slow}, fast at ${fast}. Equality after moving detects a cycle.`,\n    });\n    if (slow === fast) return true;\n  }\n  return false;\n}",
  "stackOps": "function stackOps({ operations }, emit = () => {}) {\n  const stack = [],\n    removed = [];\n  for (const [op, value] of operations) {\n    if (op === \"push\") stack.push(value);\n    else removed.push(stack.length ? stack.pop() : null);\n    emit({\n      kind: \"stack\",\n      values: stack,\n      active: [stack.length - 1],\n      auxiliary: removed,\n      note: `${op}${op === \"push\" ? ` ${value}` : \"\"}; top is the last element. null means an empty pop.`,\n    });\n  }\n  return { stack, removed };\n}",
  "brackets": "function brackets({ text }, emit = () => {}) {\n  const stack = [],\n    pairs = { \")\": \"(\", \"]\": \"[\", \"}\": \"{\" };\n  for (let i = 0; i < text.length; i++) {\n    const c = text[i];\n    if (\"([{ \".trim().includes(c)) stack.push(c);\n    else if (Object.hasOwn(pairs, c) && stack.pop() !== pairs[c]) {\n      emit({\n        values: [...text],\n        active: [i],\n        auxiliary: stack,\n        note: \"Closing bracket does not match the most recent opener.\",\n      });\n      return false;\n    }\n    emit({\n      values: [...text],\n      active: [i],\n      auxiliary: stack,\n      note: `Process ${c}; stack contains unmatched opening brackets.`,\n    });\n  }\n  return stack.length === 0;\n}",
  "postfix": "function postfix({ tokens }, emit = () => {}) {\n  const stack = [];\n  for (const token of tokens) {\n    if (![\"+\", \"-\", \"*\", \"/\"].includes(token)) stack.push(Number(token));\n    else {\n      if (stack.length < 2) throw new Error(\"Missing operand\");\n      const right = stack.pop(),\n        left = stack.pop();\n      stack.push(\n        token === \"+\"\n          ? left + right\n          : token === \"-\"\n            ? left - right\n            : token === \"*\"\n              ? left * right\n              : left / right,\n      );\n    }\n    emit({\n      kind: \"stack\",\n      values: stack,\n      note: `Process token ${token}; pop right operand before left operand.`,\n    });\n  }\n  if (stack.length !== 1) throw new Error(\"Malformed postfix expression\");\n  return stack[0];\n}",
  "nextGreater": "function nextGreater({ values }, emit = () => {}) {\n  const stack = [],\n    result = Array(values.length).fill(-1);\n  for (let i = 0; i < values.length; i++) {\n    while (stack.length && values[stack.at(-1)] < values[i]) result[stack.pop()] = values[i];\n    stack.push(i);\n    emit({\n      values,\n      active: [...stack],\n      auxiliary: result,\n      note: `At ${i}: stack holds unresolved indices with nonincreasing values.`,\n    });\n  }\n  return result;\n}",
  "queueOps": "function queueOps({ operations, capacity }, emit = () => {}) {\n  const slots = Array(capacity).fill(null),\n    removed = [];\n  let head = 0,\n    size = 0;\n  for (const [op, value] of operations) {\n    let note;\n    if (op === \"enqueue\") {\n      if (size === capacity) note = \"Full: insertion rejected; unread data is preserved.\";\n      else {\n        const tail = (head + size) % capacity;\n        slots[tail] = value;\n        size++;\n        note = `Write ${value} at slot ${tail}.`;\n      }\n    } else if (size === 0) {\n      removed.push(null);\n      note = \"Empty: return null.\";\n    } else {\n      removed.push(slots[head]);\n      slots[head] = null;\n      head = (head + 1) % capacity;\n      size--;\n      note = \"Remove oldest item and advance head modulo capacity.\";\n    }\n    emit({\n      values: slots,\n      active: [head],\n      auxiliary: removed,\n      note: `${note} head=${head}, size=${size}, next write=${(head + size) % capacity}.`,\n    });\n  }\n  return { values: Array.from({ length: size }, (_, i) => slots[(head + i) % capacity]), removed };\n}",
  "dequeWindow": "function dequeWindow({ values, size }, emit = () => {}) {\n  const deque = [],\n    result = [];\n  for (let i = 0; i < values.length; i++) {\n    while (deque.length && deque[0] <= i - size) deque.shift();\n    while (deque.length && values[deque.at(-1)] <= values[i]) deque.pop();\n    deque.push(i);\n    if (i >= size - 1) result.push(values[deque[0]]);\n    emit({\n      values,\n      active: [...deque],\n      auxiliary: result,\n      note: `At ${i}: candidate indices in decreasing value order; front is the maximum.`,\n    });\n  }\n  return result;\n}",
  "hashChain": "function hashChain({ values, capacity }, emit = () => {}) {\n  const buckets = Array.from({ length: capacity }, () => []);\n  for (const value of values) {\n    const slot = ((value % capacity) + capacity) % capacity;\n    if (!buckets[slot].includes(value)) buckets[slot].push(value);\n    emit({\n      kind: \"buckets\",\n      values: buckets.map((b) => b.join(\" → \") || \"∅\"),\n      active: [slot],\n      note: `${value} hashes to ${slot}; compare full keys within its chain.`,\n    });\n  }\n  return buckets;\n}",
  "hashProbe": "function hashProbe({ values, capacity }, emit = () => {}) {\n  const table = Array(capacity).fill(null);\n  for (const value of values) {\n    let slot = ((value % capacity) + capacity) % capacity,\n      probes = 0;\n    while (table[slot] !== null && table[slot] !== value && probes < capacity) {\n      emit({ values: table, active: [slot], note: `Collision for ${value}; try the next slot.` });\n      slot = (slot + 1) % capacity;\n      probes++;\n    }\n    if (probes === capacity) throw new Error(\"Hash table is full\");\n    table[slot] = value;\n    emit({ values: table, active: [slot], note: `Store ${value} at slot ${slot}.` });\n  }\n  return table;\n}",
  "frequencies": "function frequencies({ values }, emit = () => {}) {\n  const counts = new Map();\n  for (const value of values) {\n    counts.set(value, (counts.get(value) || 0) + 1);\n    emit({\n      kind: \"buckets\",\n      values: [...counts].map(([k, v]) => `${k}: ${v}`),\n      note: `Count one occurrence of ${value}; preserve multiplicity rather than only membership.`,\n    });\n  }\n  return [...counts];\n}",
  "binarySearch": "function binarySearch({ values, target, lowerBound = false }, emit = () => {}) {\n  let lo = 0,\n    hi = values.length;\n  while (lo < hi) {\n    const mid = lo + Math.floor((hi - lo) / 2);\n    emit({\n      values,\n      active: [mid],\n      range: [lo, hi],\n      note: `Candidate interval [${lo}, ${hi}); mid=${mid}, value=${values[mid]}.`,\n    });\n    if (values[mid] < target) lo = mid + 1;\n    else hi = mid;\n  }\n  emit({\n    values,\n    active: lo < values.length ? [lo] : [],\n    range: [lo, lo],\n    note: `Insertion boundary is ${lo}; verify equality for exact search.`,\n  });\n  return lowerBound ? lo : values[lo] === target ? lo : -1;\n}",
  "bubbleSort": "function bubbleSort({ values }, emit = () => {}) {\n  const a = [...values];\n  for (let end = a.length - 1; end > 0; end--) {\n    let changed = false;\n    for (let i = 0; i < end; i++) {\n      if (a[i] > a[i + 1]) {\n        [a[i], a[i + 1]] = [a[i + 1], a[i]];\n        changed = true;\n      }\n      emit({\n        values: a,\n        active: [i, i + 1],\n        note: `Compare adjacent positions; after the pass, position ${end} is final.`,\n      });\n    }\n    if (!changed) break;\n  }\n  return a;\n}",
  "insertionSort": "function insertionSort({ values }, emit = () => {}) {\n  const a = [...values];\n  for (let i = 1; i < a.length; i++) {\n    const key = a[i];\n    let j = i - 1;\n    while (j >= 0 && a[j] > key) {\n      a[j + 1] = a[j];\n      emit({\n        values: a,\n        active: [j, j + 1],\n        auxiliary: [key],\n        note: `Keep key=${key} aside and shift the larger value right.`,\n      });\n      j--;\n    }\n    a[j + 1] = key;\n    emit({ values: a, active: [j + 1], note: `Insert key; prefix [0, ${i + 1}) is sorted.` });\n  }\n  return a;\n}",
  "selectionSort": "function selectionSort({ values }, emit = () => {}) {\n  const a = [...values];\n  for (let i = 0; i < a.length; i++) {\n    let smallest = i;\n    for (let j = i + 1; j < a.length; j++) {\n      if (a[j] < a[smallest]) smallest = j;\n      emit({\n        values: a,\n        active: [j, smallest],\n        note: `Find the smallest remaining value for position ${i}.`,\n      });\n    }\n    [a[i], a[smallest]] = [a[smallest], a[i]];\n    emit({ values: a, active: [i], note: `Position ${i} is now final.` });\n  }\n  return a;\n}",
  "mergeSort": "function mergeSort({ values }, emit = () => {}) {\n  function sort(a) {\n    if (a.length < 2) return a;\n    const mid = Math.floor(a.length / 2);\n    emit({ values: a, active: [mid], note: `Split into lengths ${mid} and ${a.length - mid}.` });\n    const left = sort(a.slice(0, mid)),\n      right = sort(a.slice(mid)),\n      merged = [];\n    let i = 0,\n      j = 0;\n    while (i < left.length || j < right.length) {\n      if (j === right.length || (i < left.length && left[i] <= right[j])) merged.push(left[i++]);\n      else merged.push(right[j++]);\n      emit({\n        values: merged,\n        auxiliary: [...left.slice(i), ...right.slice(j)],\n        note: \"Take the smaller front value; ties come from the left, preserving stability.\",\n      });\n    }\n    return merged;\n  }\n  return sort([...values]);\n}",
  "quickSort": "function quickSort({ values }, emit = () => {}) {\n  const a = [...values];\n  function sort(lo, hi) {\n    if (lo >= hi) return;\n    const pivot = a[hi];\n    let boundary = lo;\n    for (let i = lo; i < hi; i++) {\n      if (a[i] < pivot) {\n        [a[i], a[boundary]] = [a[boundary], a[i]];\n        boundary++;\n      }\n      emit({\n        values: a,\n        active: [i, hi],\n        range: [lo, hi + 1],\n        note: `Pivot=${pivot}; values before ${boundary} are smaller than it.`,\n      });\n    }\n    [a[boundary], a[hi]] = [a[hi], a[boundary]];\n    emit({\n      values: a,\n      active: [boundary],\n      note: \"Pivot reaches its final position; recurse on the two sides.\",\n    });\n    sort(lo, boundary - 1);\n    sort(boundary + 1, hi);\n  }\n  sort(0, a.length - 1);\n  return a;\n}",
  "countingSort": "function countingSort({ values }, emit = () => {}) {\n  if (!values.length) return [];\n  const count = Array(Math.max(...values) + 1).fill(0);\n  for (const value of values) {\n    if (!Number.isInteger(value) || value < 0) throw new Error(\"Use nonnegative integers\");\n    count[value]++;\n    emit({\n      values: count,\n      active: [value],\n      note: `Increment frequency of key ${value}. Slot index is the key.`,\n    });\n  }\n  const result = [];\n  count.forEach((n, value) => {\n    for (let i = 0; i < n; i++) result.push(value);\n  });\n  emit({ values: result, note: \"Expand frequencies in increasing key order.\" });\n  return result;\n}",
  "heapSort": "function heapSort({ values }, emit = () => {}) {\n  const a = [...values];\n  function sift(root, size) {\n    while (2 * root + 1 < size) {\n      let child = 2 * root + 1;\n      if (child + 1 < size && a[child + 1] > a[child]) child++;\n      if (a[root] >= a[child]) break;\n      [a[root], a[child]] = [a[child], a[root]];\n      emit({\n        kind: \"tree\",\n        values: a.slice(0, size),\n        active: [root, child],\n        auxiliary: a.slice(size),\n        note: `Sift down within heap size ${size}; larger child moves up. Bottom row is the finalized sorted suffix.`,\n      });\n      root = child;\n    }\n  }\n  for (let i = Math.floor(a.length / 2) - 1; i >= 0; i--) sift(i, a.length);\n  emit({ kind: \"tree\", values: a, note: \"Bottom-up construction gives a max-heap.\" });\n  for (let end = a.length - 1; end > 0; end--) {\n    [a[0], a[end]] = [a[end], a[0]];\n    emit({ values: a, active: [end], note: `Maximum goes to sorted suffix at ${end}.` });\n    sift(0, end);\n  }\n  return a;\n}",
  "heapInsert": "function heapInsert({ values }, emit = () => {}) {\n  const heap = [];\n  for (const value of values) {\n    heap.push(value);\n    let i = heap.length - 1;\n    emit({\n      kind: \"tree\",\n      values: heap,\n      active: [i],\n      note: `Append ${value} at the next complete-tree position.`,\n    });\n    while (i > 0) {\n      const parent = Math.floor((i - 1) / 2);\n      if (heap[parent] <= heap[i]) break;\n      [heap[parent], heap[i]] = [heap[i], heap[parent]];\n      i = parent;\n      emit({\n        kind: \"tree\",\n        values: heap,\n        active: [i],\n        note: \"Swap upward until the min-heap order is restored.\",\n      });\n    }\n  }\n  return heap;\n}",
  "treeTraversal": "function treeTraversal({ values, order = \"inorder\" }, emit = () => {}) {\n  const result = [];\n  function visit(i) {\n    if (i >= values.length || values[i] === null) return;\n    const take = () => {\n      result.push(values[i]);\n      emit({\n        kind: \"tree\",\n        values,\n        active: [i],\n        auxiliary: result,\n        note: `${order}: visit ${values[i]}.`,\n      });\n    };\n    if (order === \"preorder\") take();\n    visit(2 * i + 1);\n    if (order === \"inorder\") take();\n    visit(2 * i + 2);\n    if (order === \"postorder\") take();\n  }\n  visit(0);\n  return result;\n}",
  "bstSearch": "function bstSearch({ values, target }, emit = () => {}) {\n  let i = 0;\n  while (i < values.length && values[i] !== null) {\n    emit({\n      kind: \"tree\",\n      values,\n      active: [i],\n      note: `Compare ${target} with node ${values[i]}; discard one entire subtree.`,\n    });\n    if (values[i] === target) return true;\n    i = target < values[i] ? 2 * i + 1 : 2 * i + 2;\n  }\n  return false;\n}",
  "bfs": "function bfs({ adjacency, start }, emit = () => {}) {\n  const queue = [start],\n    seen = new Set([start]),\n    result = [];\n  const edges = adjacency.flatMap((neighbors, from) => neighbors.map((to) => [from, to]));\n  for (let head = 0; head < queue.length; head++) {\n    const u = queue[head];\n    result.push(u);\n    for (const v of adjacency[u])\n      if (!seen.has(v)) {\n        seen.add(v);\n        queue.push(v);\n      }\n    emit({\n      kind: \"graph\",\n      values: adjacency.map((_, i) => i),\n      edges,\n      active: [u],\n      visited: [...seen],\n      auxiliary: queue.slice(head + 1),\n      note: `Visit ${u}; enqueue previously unseen neighbors. Bottom row is the pending queue.`,\n    });\n  }\n  return result;\n}",
  "dfs": "function dfs({ adjacency, start }, emit = () => {}) {\n  const seen = new Set(),\n    result = [],\n    stack = [];\n  const edges = adjacency.flatMap((neighbors, from) => neighbors.map((to) => [from, to]));\n  function visit(u) {\n    seen.add(u);\n    stack.push(u);\n    result.push(u);\n    emit({\n      kind: \"graph\",\n      values: adjacency.map((_, i) => i),\n      edges,\n      active: [u],\n      visited: [...seen],\n      auxiliary: stack,\n      note: `Enter ${u}; follow one branch before returning. Bottom row is the call stack.`,\n    });\n    for (const v of adjacency[u]) if (!seen.has(v)) visit(v);\n    stack.pop();\n  }\n  visit(start);\n  return result;\n}",
  "topological": "function topological({ adjacency }, emit = () => {}) {\n  const degree = Array(adjacency.length).fill(0),\n    queue = [],\n    result = [];\n  for (const neighbors of adjacency) for (const v of neighbors) degree[v]++;\n  degree.forEach((d, i) => {\n    if (d === 0) queue.push(i);\n  });\n  for (let head = 0; head < queue.length; head++) {\n    const u = queue[head];\n    result.push(u);\n    for (const v of adjacency[u]) if (--degree[v] === 0) queue.push(v);\n    emit({\n      kind: \"graph\",\n      values: degree.map((d, i) => `${i}:${d}`),\n      edges: adjacency.flatMap((ns, u) => ns.map((v) => [u, v])),\n      active: [u],\n      auxiliary: result,\n      note: `Remove ${u}; decrement indegrees of its successors.`,\n    });\n  }\n  return result.length === adjacency.length ? result : null;\n}",
  "dijkstra": "function dijkstra({ weights, start }, emit = () => {}) {\n  const n = weights.length,\n    distance = Array(n).fill(Infinity),\n    used = Array(n).fill(false);\n  distance[start] = 0;\n  for (let pass = 0; pass < n; pass++) {\n    let u = -1;\n    for (let i = 0; i < n; i++) if (!used[i] && (u === -1 || distance[i] < distance[u])) u = i;\n    if (u === -1 || distance[u] === Infinity) break;\n    used[u] = true;\n    for (let v = 0; v < n; v++)\n      if (weights[u][v] !== null) {\n        if (weights[u][v] < 0) throw new Error(\"Dijkstra requires nonnegative weights\");\n        distance[v] = Math.min(distance[v], distance[u] + weights[u][v]);\n      }\n    emit({\n      kind: \"graph\",\n      values: distance.map((d, i) => `${i}:${d === Infinity ? \"∞\" : d}`),\n      edges: weights.flatMap((row, from) =>\n        row.flatMap((w, to) => (w === null ? [] : [[from, to, w]])),\n      ),\n      active: [u],\n      visited: used.flatMap((v, i) => (v ? [i] : [])),\n      note: `Settle ${u} with distance ${distance[u]}, then relax its outgoing edges.`,\n    });\n  }\n  return distance.map((d) => (d === Infinity ? null : d));\n}",
  "unionFind": "function unionFind({ size, pairs }, emit = () => {}) {\n  const parent = Array.from({ length: size }, (_, i) => i),\n    rank = Array(size).fill(0);\n  function find(x) {\n    if (parent[x] !== x) parent[x] = find(parent[x]);\n    return parent[x];\n  }\n  for (const [a, b] of pairs) {\n    let ra = find(a),\n      rb = find(b);\n    if (ra !== rb) {\n      if (rank[ra] < rank[rb]) [ra, rb] = [rb, ra];\n      parent[rb] = ra;\n      if (rank[ra] === rank[rb]) rank[ra]++;\n    }\n    emit({\n      kind: \"graph\",\n      values: parent.map((_, i) => i),\n      edges: parent.flatMap((p, i) => (p === i ? [] : [[i, p]])),\n      active: [a, b],\n      auxiliary: parent,\n      note: `Union(${a}, ${b}); roots decide connectivity. Parent pointers form a forest.`,\n    });\n  }\n  return parent.map((_, i) => find(i));\n}",
  "kruskal": "function kruskal({ size, edges }, emit = () => {}) {\n  const parent = Array.from({ length: size }, (_, i) => i),\n    accepted = [];\n  const find = (x) => (parent[x] === x ? x : (parent[x] = find(parent[x])));\n  let total = 0;\n  for (const [u, v, weight] of [...edges].sort((a, b) => a[2] - b[2])) {\n    const a = find(u),\n      b = find(v),\n      take = a !== b;\n    if (take) {\n      parent[a] = b;\n      accepted.push([u, v, weight]);\n      total += weight;\n    }\n    emit({\n      kind: \"graph\",\n      undirected: true,\n      values: parent.map((_, i) => i),\n      edges: accepted,\n      active: [u, v],\n      note: `${take ? \"Accept\" : \"Reject cycle edge\"} ${u}—${v}, weight ${weight}; total=${total}.`,\n    });\n  }\n  return { edges: accepted, total };\n}",
  "trie": "function trie({ words, prefix }, emit = () => {}) {\n  const root = { children: {}, end: false };\n  for (const word of words) {\n    let node = root;\n    for (const c of word) {\n      node.children[c] ||= { children: {}, end: false };\n      node = node.children[c];\n    }\n    node.end = true;\n    const labels = [\"root\"],\n      edges = [];\n    function draw(n, id) {\n      for (const [c, child] of Object.entries(n.children)) {\n        const next = labels.length;\n        labels.push(c + (child.end ? \"*\" : \"\"));\n        edges.push([id, next]);\n        draw(child, next);\n      }\n    }\n    draw(root, 0);\n    emit({\n      kind: \"hierarchy\",\n      values: labels,\n      edges,\n      note: `Insert ${word}; shared prefixes reuse nodes. * marks the end of a stored word.`,\n    });\n  }\n  let node = root;\n  for (const c of prefix) {\n    node = node.children[c];\n    if (!node) return [];\n  }\n  const result = [];\n  function collect(n, word) {\n    if (n.end) result.push(word);\n    for (const [c, child] of Object.entries(n.children)) collect(child, word + c);\n  }\n  collect(node, prefix);\n  return result;\n}",
  "factorial": "function factorial({ n }, emit = () => {}) {\n  const stack = [];\n  function solve(k) {\n    stack.push(k);\n    emit({\n      kind: \"stack\",\n      values: stack,\n      note: `Enter factorial(${k}); each call keeps its own pending multiplication.`,\n    });\n    const result = k <= 1 ? 1 : k * solve(k - 1);\n    stack.pop();\n    emit({\n      kind: \"stack\",\n      values: stack,\n      auxiliary: [result],\n      note: `Return ${result} from factorial(${k}).`,\n    });\n    return result;\n  }\n  return solve(n);\n}",
  "hanoi": "function hanoi({ n }, emit = () => {}) {\n  const pegs = [Array.from({ length: n }, (_, i) => n - i), [], []],\n    moves = [];\n  function move(count, from, to, spare) {\n    if (!count) return;\n    move(count - 1, from, spare, to);\n    const disk = pegs[from].pop();\n    pegs[to].push(disk);\n    moves.push([from, to]);\n    emit({\n      kind: \"buckets\",\n      values: pegs.map((p) => p.join(\" · \") || \"∅\"),\n      active: [from, to],\n      note: `Move disk ${disk} from peg ${from} to ${to}. Each peg is bottom → top.`,\n    });\n    move(count - 1, spare, to, from);\n  }\n  move(n, 0, 2, 1);\n  return moves;\n}",
  "fibonacci": "function fibonacci({ n }, emit = () => {}) {\n  const dp = [0, 1];\n  for (let i = 2; i <= n; i++) {\n    dp[i] = dp[i - 1] + dp[i - 2];\n    emit({\n      values: dp,\n      active: [i - 2, i - 1, i],\n      note: `F(${i}) = ${dp[i - 1]} + ${dp[i - 2]} = ${dp[i]}.`,\n    });\n  }\n  return dp[n];\n}",
  "coinChange": "function coinChange({ coins, amount }, emit = () => {}) {\n  const dp = Array(amount + 1).fill(Infinity);\n  dp[0] = 0;\n  for (let value = 1; value <= amount; value++) {\n    for (const coin of coins)\n      if (coin <= value) dp[value] = Math.min(dp[value], 1 + dp[value - coin]);\n    emit({\n      values: dp.map((x) => (x === Infinity ? \"∞\" : x)),\n      active: [value],\n      note: `Minimum coins for ${value}: try every possible last coin.`,\n    });\n  }\n  return dp[amount] === Infinity ? -1 : dp[amount];\n}",
  "knapsack": "function knapsack({ weights, profits, capacity }, emit = () => {}) {\n  const dp = Array(capacity + 1).fill(0);\n  for (let i = 0; i < weights.length; i++) {\n    for (let cap = capacity; cap >= weights[i]; cap--) {\n      dp[cap] = Math.max(dp[cap], profits[i] + dp[cap - weights[i]]);\n      emit({\n        values: dp,\n        active: [cap, cap - weights[i]],\n        note: `Item ${i}, weight=${weights[i]}, profit=${profits[i]}; capacities decrease so each item is used at most once.`,\n      });\n    }\n  }\n  return dp[capacity];\n}",
  "lcs": "function lcs({ left, right }, emit = () => {}) {\n  const dp = Array.from({ length: left.length + 1 }, () => Array(right.length + 1).fill(0));\n  for (let i = 1; i <= left.length; i++)\n    for (let j = 1; j <= right.length; j++) {\n      dp[i][j] =\n        left[i - 1] === right[j - 1] ? 1 + dp[i - 1][j - 1] : Math.max(dp[i - 1][j], dp[i][j - 1]);\n      emit({\n        kind: \"matrix\",\n        matrix: dp,\n        activeCell: [i, j],\n        note: `Compare ${left[i - 1]} and ${right[j - 1]}; dp[${i}][${j}] is the LCS length for these prefixes.`,\n      });\n    }\n  return dp[left.length][right.length];\n}",
  "intervals": "function intervals({ intervals }, emit = () => {}) {\n  const sorted = [...intervals].sort((a, b) => a[1] - b[1]),\n    selected = [];\n  let end = -Infinity;\n  for (const item of sorted) {\n    const take = item[0] >= end;\n    if (take) {\n      selected.push(item);\n      end = item[1];\n    }\n    emit({\n      values: sorted.map(([a, b]) => `[${a},${b})`),\n      active: [sorted.indexOf(item)],\n      auxiliary: selected.map(([a, b]) => `[${a},${b})`),\n      note: `${take ? \"Accept\" : \"Reject overlap\"} [${item}); earliest finishing compatible interval preserves future room.`,\n    });\n  }\n  return selected;\n}",
  "fractional": "function fractional({ items, capacity }, emit = () => {}) {\n  let remaining = capacity,\n    total = 0;\n  const sorted = [...items].sort((a, b) => b.value / b.weight - a.value / a.weight);\n  for (const [i, item] of sorted.entries()) {\n    const fraction = Math.min(1, remaining / item.weight);\n    total += item.value * fraction;\n    remaining -= item.weight * fraction;\n    emit({\n      values: sorted.map((x) => `${x.value}/${x.weight}`),\n      active: [i],\n      auxiliary: [total, remaining],\n      note: `Take fraction ${fraction} at value/weight=${item.value / item.weight}. Bottom: total value, remaining capacity.`,\n    });\n    if (!remaining) break;\n  }\n  return total;\n}",
  "subsets": "function subsets({ values }, emit = () => {}) {\n  const path = [],\n    result = [];\n  function visit(i) {\n    if (i === values.length) {\n      result.push([...path]);\n      emit({ values, active: [], auxiliary: path, note: `Leaf: save subset [${path}].` });\n      return;\n    }\n    emit({ values, active: [i], auxiliary: path, note: `Exclude ${values[i]} first.` });\n    visit(i + 1);\n    path.push(values[i]);\n    emit({\n      values,\n      active: [i],\n      auxiliary: path,\n      note: `Include ${values[i]}; restore the choice after returning.`,\n    });\n    visit(i + 1);\n    path.pop();\n  }\n  visit(0);\n  return result;\n}",
  "permutations": "function permutations({ values }, emit = () => {}) {\n  const path = [],\n    used = Array(values.length).fill(false),\n    result = [];\n  function visit() {\n    if (path.length === values.length) {\n      result.push([...path]);\n      return;\n    }\n    for (let i = 0; i < values.length; i++)\n      if (!used[i]) {\n        used[i] = true;\n        path.push(values[i]);\n        emit({\n          values,\n          active: [i],\n          auxiliary: path,\n          note: `Choose ${values[i]}; unavailable indices are not reused on this path.`,\n        });\n        visit();\n        path.pop();\n        used[i] = false;\n        emit({\n          values,\n          auxiliary: path,\n          note: `Undo ${values[i]} before trying the next sibling branch.`,\n        });\n      }\n  }\n  visit();\n  return result;\n}",
  "queens": "function queens({ n }, emit = () => {}) {\n  const columns = [],\n    result = [];\n  function place(row) {\n    if (row === n) {\n      result.push([...columns]);\n      return;\n    }\n    for (let col = 0; col < n; col++) {\n      if (columns.some((c, r) => c === col || Math.abs(c - col) === row - r)) continue;\n      columns.push(col);\n      emit({\n        kind: \"matrix\",\n        matrix: Array.from({ length: n }, (_, r) =>\n          Array.from({ length: n }, (_, c) => (columns[r] === c ? \"Q\" : \"·\")),\n        ),\n        activeCell: [row, col],\n        note: `Place queen at row ${row}, column ${col}; column and diagonal constraints hold.`,\n      });\n      place(row + 1);\n      columns.pop();\n    }\n  }\n  place(0);\n  return result;\n}",
  "fenwick": "function fenwick({ values, end }, emit = () => {}) {\n  const tree = Array(values.length + 1).fill(0);\n  for (let i = 0; i < values.length; i++)\n    for (let j = i + 1; j < tree.length; j += j & -j) {\n      tree[j] += values[i];\n      emit({\n        values: tree,\n        active: [j],\n        note: `Add ${values[i]} to 1-based node ${j}; next ancestor is j + lowbit(j). Index 0 is unused.`,\n      });\n    }\n  let sum = 0;\n  for (let j = end; j > 0; j -= j & -j) {\n    sum += tree[j];\n    emit({\n      values: tree,\n      active: [j],\n      auxiliary: [sum],\n      note: `Collect node ${j}, then remove its lowbit. Query covers [0, ${end}).`,\n    });\n  }\n  return sum;\n}",
  "segmentTree": "function segmentTree({ values, left, right }, emit = () => {}) {\n  const n = values.length,\n    tree = Array(2 * n).fill(0);\n  for (let i = 0; i < n; i++) tree[n + i] = values[i];\n  for (let i = n - 1; i > 0; i--) {\n    tree[i] = tree[2 * i] + tree[2 * i + 1];\n    emit({\n      values: tree,\n      active: [i, 2 * i, 2 * i + 1],\n      note: `Parent ${i} combines its two children. Slots ${n} onward are leaves; slot 0 is unused.`,\n    });\n  }\n  let l = left + n,\n    r = right + n,\n    result = 0;\n  while (l < r) {\n    if (l % 2) result += tree[l++];\n    if (r % 2) result += tree[--r];\n    emit({\n      values: tree,\n      active: [l, r],\n      auxiliary: [result],\n      note: `Collect exposed boundary nodes, then move both boundaries upward.`,\n    });\n    l = Math.floor(l / 2);\n    r = Math.floor(r / 2);\n  }\n  return result;\n}",
  "bloom": "function bloom({ values, queries, size }, emit = () => {}) {\n  const bits = Array(size).fill(0);\n  const hashes = (value) => [value % size, (value * 3 + 1) % size];\n  for (const value of values) {\n    const indices = hashes(value);\n    indices.forEach((i) => {\n      bits[i] = 1;\n    });\n    emit({\n      values: bits,\n      active: indices,\n      note: `Set two toy hash positions for ${value}. Collisions share bits.`,\n    });\n  }\n  return queries.map((value) => {\n    const indices = hashes(value),\n      maybe = indices.every((i) => bits[i] === 1);\n    emit({\n      values: bits,\n      active: indices,\n      note: `Query ${value}: ${maybe ? \"possibly present; verify elsewhere\" : \"definitely absent\"}.`,\n    });\n    return maybe;\n  });\n}",
  "bitmask": "function bitmask({ values }, emit = () => {}) {\n  const result = [];\n  for (let mask = 0; mask < 2 ** values.length; mask++) {\n    const subset = values.filter((_, i) => (mask & (1 << i)) !== 0);\n    result.push(subset);\n    emit({\n      values,\n      active: values.flatMap((_, i) => (mask & (1 << i) ? [i] : [])),\n      auxiliary: subset,\n      note: `Mask ${mask.toString(2).padStart(values.length, \"0\")}; bit i selects input index i.`,\n    });\n  }\n  return result;\n}",
  "bstOperations": "function bstOperations({ operations }, emit = () => {}) {\n  let root = null;\n  function insert(node, value) {\n    if (!node) return { value, left: null, right: null };\n    if (value < node.value) node.left = insert(node.left, value);\n    else if (value > node.value) node.right = insert(node.right, value);\n    return node;\n  }\n  function remove(node, value) {\n    if (!node) return null;\n    if (value < node.value) node.left = remove(node.left, value);\n    else if (value > node.value) node.right = remove(node.right, value);\n    else {\n      if (!node.left) return node.right;\n      if (!node.right) return node.left;\n      let successor = node.right;\n      while (successor.left) successor = successor.left;\n      node.value = successor.value;\n      node.right = remove(node.right, successor.value);\n    }\n    return node;\n  }\n  function draw(node) {\n    const values = [],\n      edges = [];\n    function visit(n, parent = null) {\n      if (!n) return;\n      const id = values.length;\n      values.push(n.value);\n      if (parent !== null) edges.push([parent, id]);\n      visit(n.left, id);\n      visit(n.right, id);\n    }\n    visit(node);\n    return { kind: \"hierarchy\", values, edges };\n  }\n  for (const [op, value] of operations) {\n    root = op === \"insert\" ? insert(root, value) : remove(root, value);\n    emit({\n      ...draw(root),\n      note: `${op} ${value}; all left descendants remain smaller and all right descendants larger. Duplicate inserts are ignored.`,\n    });\n  }\n  const result = [];\n  function inorder(n) {\n    if (n) {\n      inorder(n.left);\n      result.push(n.value);\n      inorder(n.right);\n    }\n  }\n  inorder(root);\n  return result;\n}",
  "avlInsert": "function avlInsert({ values }, emit = () => {}) {\n  const height = (n) => (n ? n.height : 0);\n  const update = (n) => {\n    n.height = 1 + Math.max(height(n.left), height(n.right));\n    return n;\n  };\n  function right(y) {\n    const x = y.left;\n    y.left = x.right;\n    x.right = y;\n    update(y);\n    return update(x);\n  }\n  function left(x) {\n    const y = x.right;\n    x.right = y.left;\n    y.left = x;\n    update(x);\n    return update(y);\n  }\n  function insert(n, value) {\n    if (!n) return { value, height: 1, left: null, right: null };\n    if (value < n.value) n.left = insert(n.left, value);\n    else if (value > n.value) n.right = insert(n.right, value);\n    else return n;\n    update(n);\n    const balance = height(n.left) - height(n.right);\n    if (balance > 1) {\n      if (value > n.left.value) n.left = left(n.left);\n      return right(n);\n    }\n    if (balance < -1) {\n      if (value < n.right.value) n.right = right(n.right);\n      return left(n);\n    }\n    return n;\n  }\n  let root = null;\n  for (const value of values) {\n    root = insert(root, value);\n    const labels = [],\n      edges = [];\n    function draw(n, parent = null) {\n      if (!n) return;\n      const id = labels.length;\n      labels.push(`${n.value} h${n.height}`);\n      if (parent !== null) edges.push([parent, id]);\n      draw(n.left, id);\n      draw(n.right, id);\n    }\n    draw(root);\n    emit({\n      kind: \"hierarchy\",\n      values: labels,\n      edges,\n      note: `Insert ${value}, update heights bottom-up, and rotate wherever the balance magnitude exceeds 1.`,\n    });\n  }\n  const order = [];\n  function walk(n) {\n    if (n) {\n      walk(n.left);\n      order.push(n.value);\n      walk(n.right);\n    }\n  }\n  walk(root);\n  return { root: root?.value ?? null, height: height(root), inorder: order };\n}",
  "matrixTranspose": "function matrixTranspose({ matrix }, emit = () => {}) {\n  if (!matrix.length) return [];\n  const result = Array.from({ length: matrix[0].length }, () => Array(matrix.length).fill(null));\n  for (let r = 0; r < matrix.length; r++)\n    for (let c = 0; c < matrix[0].length; c++) {\n      result[c][r] = matrix[r][c];\n      emit({\n        kind: \"matrix\",\n        matrix: result,\n        activeCell: [c, r],\n        note: `Copy input[${r}][${c}]=${matrix[r][c]} to output[${c}][${r}].`,\n      });\n    }\n  return result;\n}",
  "radixSort": "function radixSort({ values }, emit = () => {}) {\n  let a = [...values];\n  const maximum = Math.max(0, ...a);\n  for (let place = 1; Math.floor(maximum / place) > 0; place *= 10) {\n    const buckets = Array.from({ length: 10 }, () => []);\n    for (const value of a) buckets[Math.floor(value / place) % 10].push(value);\n    emit({\n      kind: \"buckets\",\n      values: buckets.map((b) => b.join(\", \") || \"∅\"),\n      note: `Stable buckets for digit place ${place}; preserve incoming order within each bucket.`,\n    });\n    a = buckets.flat();\n    emit({\n      values: a,\n      note: `Gather digit ${place}; lower processed digits remain correctly ordered within ties.`,\n    });\n  }\n  return a;\n}",
  "fastPower": "function fastPower({ base, exponent }, emit = () => {}) {\n  let result = 1,\n    power = base,\n    remaining = exponent;\n  while (remaining > 0) {\n    if (remaining % 2 === 1) result *= power;\n    remaining = Math.floor(remaining / 2);\n    power *= power;\n    emit({\n      values: [result, power, remaining],\n      note: \"State: accumulated result, current squared power, remaining exponent. Consume one binary digit per iteration.\",\n    });\n  }\n  return result;\n}",
  "bellmanFord": "function bellmanFord({ size, edges, start }, emit = () => {}) {\n  const distance = Array(size).fill(Infinity);\n  distance[start] = 0;\n  for (let pass = 1; pass < size; pass++) {\n    let changed = false;\n    for (const [u, v, w] of edges)\n      if (distance[u] !== Infinity && distance[u] + w < distance[v]) {\n        distance[v] = distance[u] + w;\n        changed = true;\n        emit({\n          kind: \"graph\",\n          values: distance.map((d, i) => `${i}:${d === Infinity ? \"∞\" : d}`),\n          edges,\n          active: [u, v],\n          note: `Pass ${pass}: relax ${u}→${v}, weight ${w}.`,\n        });\n      }\n    if (!changed) break;\n  }\n  const negativeCycle = edges.some(\n    ([u, v, w]) => distance[u] !== Infinity && distance[u] + w < distance[v],\n  );\n  return { distance: distance.map((d) => (d === Infinity ? null : d)), negativeCycle };\n}",
  "floydWarshall": "function floydWarshall({ matrix }, emit = () => {}) {\n  const d = matrix.map((row) => row.map((x) => (x === null ? Infinity : x)));\n  for (let k = 0; k < d.length; k++) {\n    for (let i = 0; i < d.length; i++)\n      for (let j = 0; j < d.length; j++) d[i][j] = Math.min(d[i][j], d[i][k] + d[k][j]);\n    emit({\n      kind: \"matrix\",\n      matrix: d.map((row) => row.map((x) => (x === Infinity ? \"∞\" : x))),\n      note: `Allow vertex ${k} as an intermediate; compare direct distance with distance through ${k}.`,\n    });\n  }\n  return d.map((row) => row.map((x) => (x === Infinity ? null : x)));\n}",
  "lru": "function lru({ requests, capacity }, emit = () => {}) {\n  const cache = new Map();\n  let hits = 0;\n  for (const key of requests) {\n    const hit = cache.has(key);\n    if (hit) {\n      hits++;\n      cache.delete(key);\n    }\n    cache.set(key, true);\n    if (cache.size > capacity) cache.delete(cache.keys().next().value);\n    emit({\n      kind: \"linked\",\n      values: [...cache.keys()],\n      active: [cache.size - 1],\n      note: `${key}: ${hit ? \"hit; move to newest\" : \"miss; insert and evict oldest if full\"}. Left is least recent, right most recent.`,\n    });\n  }\n  return { keys: [...cache.keys()], hits };\n}",
  "mergeLists": "function mergeLists({ left, right }, emit = () => {}) {\n  const result = [];\n  let i = 0,\n    j = 0;\n  while (i < left.length || j < right.length) {\n    if (j === right.length || (i < left.length && left[i] <= right[j])) result.push(left[i++]);\n    else result.push(right[j++]);\n    emit({\n      kind: \"linked\",\n      values: result,\n      auxiliary: [...left.slice(i), ...right.slice(j)],\n      note: \"Take the smaller current head and advance only that input. Top: merged prefix; bottom: remaining inputs concatenated for display.\",\n    });\n  }\n  return result;\n}",
  "skipSearch": "function skipSearch({ levels, target }, emit = () => {}) {\n  let predecessor = -Infinity;\n  for (let level = levels.length - 1; level >= 0; level--) {\n    for (const value of levels[level])\n      if (value >= predecessor && value < target) predecessor = value;\n    emit({\n      kind: \"buckets\",\n      values: levels.map((row) => row.join(\" → \")),\n      active: [level],\n      auxiliary: [predecessor === -Infinity ? \"head\" : predecessor],\n      note: `Level ${level}: move right while below ${target}, then descend. This array-backed teaching scan illustrates routing, not skip-list pointer complexity.`,\n    });\n  }\n  return levels[0].includes(target);\n}",
  "redBlackInsert": "function redBlackInsert({ values }, emit = () => {}) {\n  const red = (n) => Boolean(n?.red);\n  function left(h) {\n    const x = h.right;\n    h.right = x.left;\n    x.left = h;\n    x.red = h.red;\n    h.red = true;\n    return x;\n  }\n  function right(h) {\n    const x = h.left;\n    h.left = x.right;\n    x.right = h;\n    x.red = h.red;\n    h.red = true;\n    return x;\n  }\n  function insert(h, value) {\n    if (!h) return { value, red: true, left: null, right: null };\n    if (value < h.value) h.left = insert(h.left, value);\n    else if (value > h.value) h.right = insert(h.right, value);\n    if (red(h.right) && !red(h.left)) h = left(h);\n    if (red(h.left) && red(h.left.left)) h = right(h);\n    if (red(h.left) && red(h.right)) {\n      h.red = !h.red;\n      h.left.red = !h.left.red;\n      h.right.red = !h.right.red;\n    }\n    return h;\n  }\n  let root = null;\n  for (const value of values) {\n    root = insert(root, value);\n    root.red = false;\n    const labels = [],\n      edges = [];\n    function draw(n, parent = null) {\n      if (!n) return;\n      const id = labels.length;\n      labels.push(`${n.value} ${n.red ? \"R\" : \"B\"}`);\n      if (parent !== null) edges.push([parent, id]);\n      draw(n.left, id);\n      draw(n.right, id);\n    }\n    draw(root);\n    emit({\n      kind: \"hierarchy\",\n      values: labels,\n      edges,\n      note: `Insert ${value}; repair right-leaning red links, consecutive left reds, and temporary 4-nodes. Force the root black.`,\n    });\n  }\n  const order = [];\n  function walk(n) {\n    if (n) {\n      walk(n.left);\n      order.push(n.value);\n      walk(n.right);\n    }\n  }\n  walk(root);\n  return order;\n}",
  "btreeInsert": "function btreeInsert({ values, degree = 2 }, emit = () => {}) {\n  let root = { keys: [], children: [] };\n  function split(parent, i) {\n    const child = parent.children[i];\n    const right = {\n      keys: child.keys.splice(degree),\n      children: child.children.length ? child.children.splice(degree) : [],\n    };\n    const middle = child.keys.pop();\n    parent.keys.splice(i, 0, middle);\n    parent.children.splice(i + 1, 0, right);\n  }\n  function insert(node, value) {\n    let i = 0;\n    while (i < node.keys.length && value > node.keys[i]) i++;\n    if (node.keys[i] === value) return;\n    if (!node.children.length) {\n      node.keys.splice(i, 0, value);\n      return;\n    }\n    if (node.children[i].keys.length === 2 * degree - 1) {\n      split(node, i);\n      if (value === node.keys[i]) return;\n      if (value > node.keys[i]) i++;\n    }\n    insert(node.children[i], value);\n  }\n  for (const value of values) {\n    if (root.keys.length === 2 * degree - 1) {\n      root = { keys: [], children: [root] };\n      split(root, 0);\n    }\n    insert(root, value);\n    const labels = [],\n      edges = [];\n    function draw(n, parent = null) {\n      const id = labels.length;\n      labels.push(n.keys.join(\"|\"));\n      if (parent !== null) edges.push([parent, id]);\n      n.children.forEach((c) => draw(c, id));\n    }\n    draw(root);\n    emit({\n      kind: \"hierarchy\",\n      values: labels,\n      edges,\n      note: `Insert ${value}; split full children before descending. All leaves stay at the same depth.`,\n    });\n  }\n  return root;\n}",
  "treapInsert": "function treapInsert({ entries }, emit = () => {}) {\n  function rotateRight(y) {\n    const x = y.left;\n    y.left = x.right;\n    x.right = y;\n    return x;\n  }\n  function rotateLeft(x) {\n    const y = x.right;\n    x.right = y.left;\n    y.left = x;\n    return y;\n  }\n  function insert(n, key, priority) {\n    if (!n) return { key, priority, left: null, right: null };\n    if (key < n.key) {\n      n.left = insert(n.left, key, priority);\n      if (n.left.priority < n.priority) n = rotateRight(n);\n    } else if (key > n.key) {\n      n.right = insert(n.right, key, priority);\n      if (n.right.priority < n.priority) n = rotateLeft(n);\n    }\n    return n;\n  }\n  let root = null;\n  for (const [key, priority] of entries) {\n    root = insert(root, key, priority);\n    const labels = [],\n      edges = [];\n    function draw(n, parent = null) {\n      if (!n) return;\n      const id = labels.length;\n      labels.push(`${n.key}/p${n.priority}`);\n      if (parent !== null) edges.push([parent, id]);\n      draw(n.left, id);\n      draw(n.right, id);\n    }\n    draw(root);\n    emit({\n      kind: \"hierarchy\",\n      values: labels,\n      edges,\n      note: `Insert key ${key} with priority ${priority}; rotate to satisfy BST key order and min-heap priority order.`,\n    });\n  }\n  const order = [];\n  function walk(n) {\n    if (n) {\n      walk(n.left);\n      order.push(n.key);\n      walk(n.right);\n    }\n  }\n  walk(root);\n  return order;\n}",
  "lazyRangeAdd": "function lazyRangeAdd(\n  { values, left, right, delta, queryLeft, queryRight },\n  emit = () => {},\n) {\n  function build(lo, hi) {\n    if (hi - lo === 1) return { lo, hi, sum: values[lo], lazy: 0, a: null, b: null };\n    const mid = Math.floor((lo + hi) / 2),\n      a = build(lo, mid),\n      b = build(mid, hi);\n    return { lo, hi, sum: a.sum + b.sum, lazy: 0, a, b };\n  }\n  const root = build(0, values.length);\n  function snapshot(note) {\n    const labels = [],\n      edges = [];\n    function draw(n, parent = null) {\n      const id = labels.length;\n      labels.push(`${n.sum}/+${n.lazy}`);\n      if (parent !== null) edges.push([parent, id]);\n      if (n.a) {\n        draw(n.a, id);\n        draw(n.b, id);\n      }\n    }\n    draw(root);\n    emit({ kind: \"hierarchy\", values: labels, edges, note });\n  }\n  function apply(n, add) {\n    n.sum += add * (n.hi - n.lo);\n    n.lazy += add;\n  }\n  function push(n) {\n    if (n.a && n.lazy) {\n      apply(n.a, n.lazy);\n      apply(n.b, n.lazy);\n      n.lazy = 0;\n    }\n  }\n  function update(n) {\n    if (right <= n.lo || n.hi <= left) return;\n    if (left <= n.lo && n.hi <= right) {\n      apply(n, delta);\n      snapshot(\n        `Tag interval [${n.lo},${n.hi}) with +${delta}. Labels show sum / pending addition. Ancestors are recomputed on return.`,\n      );\n      return;\n    }\n    push(n);\n    update(n.a);\n    update(n.b);\n    n.sum = n.a.sum + n.b.sum;\n  }\n  function query(n) {\n    if (queryRight <= n.lo || n.hi <= queryLeft) return 0;\n    if (queryLeft <= n.lo && n.hi <= queryRight) return n.sum;\n    push(n);\n    snapshot(`Push pending work before partially querying [${n.lo},${n.hi}).`);\n    return query(n.a) + query(n.b);\n  }\n  snapshot(\"Initial tree: labels show sum / pending addition.\");\n  update(root);\n  snapshot(\"Update complete: parent sums include the change even where child tags remain pending.\");\n  const sum = query(root);\n  return { sum, total: root.sum };\n}",
  "trieDelete": "function trieDelete({ words, remove }, emit = () => {}) {\n  const root = { children: {}, end: false };\n  for (const word of words) {\n    let n = root;\n    for (const c of word) {\n      n.children[c] ||= { children: {}, end: false };\n      n = n.children[c];\n    }\n    n.end = true;\n  }\n  function snapshot(note) {\n    const labels = [\"root\"],\n      edges = [];\n    function draw(n, id) {\n      for (const [c, child] of Object.entries(n.children)) {\n        const next = labels.length;\n        labels.push(c + (child.end ? \"*\" : \"\"));\n        edges.push([id, next]);\n        draw(child, next);\n      }\n    }\n    draw(root, 0);\n    emit({ kind: \"hierarchy\", values: labels, edges, note });\n  }\n  snapshot(\"Initial words share prefixes; * marks terminal nodes.\");\n  function erase(n, word, i) {\n    if (i === word.length) n.end = false;\n    else {\n      const child = n.children[word[i]];\n      if (!child) return false;\n      if (erase(child, word, i + 1)) {\n        delete n.children[word[i]];\n        snapshot(`Prune child ${word[i]} only after it becomes childless and nonterminal.`);\n      }\n    }\n    return !n.end && Object.keys(n.children).length === 0;\n  }\n  for (const word of remove) {\n    erase(root, word, 0);\n    snapshot(`Finished deleting ${word}; other terminal paths remain reachable.`);\n  }\n  const result = [];\n  function collect(n, prefix) {\n    if (n.end) result.push(prefix);\n    for (const [c, child] of Object.entries(n.children)) collect(child, prefix + c);\n  }\n  collect(root, \"\");\n  return result;\n}"
};
